def genLocalVars(sc, start):
  for i in range(start, len(sc)):
    if type(sc[i]) == Var:
      asm.append('(local $' + sc[i].name + ' i32)')
  asm.append('(local $0 i32)')  # auxiliary local variable
  return sc[start:]
